package ibex_tracer_pkg;

  parameter int unsigned TracePkgIdW = 4;
  parameter int unsigned TracePkgAddrW = 32;
  parameter int unsigned TracePkgDataW = 32;

  typedef struct packed {
    logic [4:0]  rs1_addr;
    logic [4:0]  rs2_addr;
    logic [31:0] pc;
    logic [31:0] instr;
    logic        instr_compressed;
    logic        branch;
    logic [31:0] branch_target;
    logic        exception;
    logic [5:0]  exception_cause;
    logic [31:0] exception_addr;
    logic [4:0]  rd_addr;
    logic [31:0] rd_wdata;
    logic        rvfi_valid;
    logic [63:0] order;
  } rvfi_trace_t;

endpackage

// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

`include "prim_assert.sv"

module ibex_counter #(
  parameter int unsigned CounterWidth = 32,
  parameter bit          Stub         = 1'b0
) (
  input  logic                  clk_i,
  input  logic                  rst_ni,
  input  logic                  counter_inc_i,
  input  logic                  counterh_we_i,
  input  logic                  counter_we_i,
  input  logic [31:0]           counter_val_i,
  output logic [63:0]           counter_val_o
);

  if (Stub) begin : gen_stub
    assign counter_val_o = '0;
  end else begin : gen_counter
    logic [CounterWidth-1:0] counter_q, counter_d;
    logic [CounterWidth-1:0] counter_load;
    logic                    counter_we;

    assign counter_we = counter_we_i | counterh_we_i;

    if (CounterWidth > 32) begin : gen_counter_wide
      assign counter_load[31:0]           = counter_we_i   ? counter_val_i : counter_q[31:0];
      assign counter_load[CounterWidth-1:32] = counterh_we_i ? counter_val_i : counter_q[CounterWidth-1:32];
    end else begin : gen_counter_32
      assign counter_load = counter_val_i;
    end

    assign counter_d = counter_we ? counter_load :
                       counter_inc_i ? counter_q + {{CounterWidth-1{1'b0}}, 1'b1} :
                       counter_q;

    if (CounterWidth > 32) begin : gen_q_wide
      logic [CounterWidth-1:0] counter_q_val;
      always_ff @(posedge clk_i or negedge rst_ni) begin
        if (!rst_ni) begin
          counter_q_val <= '0;
        end else begin
          counter_q_val <= counter_d;
        end
      end
      assign counter_q = counter_q_val;
    end else begin : gen_q_32
      always_ff @(posedge clk_i or negedge rst_ni) begin
        if (!rst_ni) begin
          counter_q <= '0;
        end else begin
          counter_q <= counter_d;
        end
      end
    end

    if (CounterWidth < 64) begin : gen_narrow
      assign counter_val_o = {{64-CounterWidth{1'b0}}, counter_q};
    end else begin : gen_full
      assign counter_val_o = counter_q;
    end
  end

endmodule

// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

module ibex_csr #(
  parameter logic [31:0] InitVal = '0
) (
  input  logic        clk_i,
  input  logic        rst_ni,
  input  logic        wr_i,
  input  logic [31:0] wr_data_i,
  output logic [31:0] rd_data_o
);

  logic [31:0] rdata_q;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      rdata_q <= InitVal;
    end else if (wr_i) begin
      rdata_q <= wr_data_i;
    end
  end

  assign rd_data_o = rdata_q;

endmodule

