`include "prim_assert.sv"

module ibex_pmp #(
  parameter bit          PMPGranularity   = 1'b0,
  parameter int unsigned PMPNumRegions    = 4,
  parameter int unsigned DataWidth        = 32
) (
  input  logic                   clk_i,
  input  logic                   rst_ni,
  input  logic [11:0]            csr_addr_i,
  input  logic [31:0]            csr_wdata_i,
  input  ibex_pkg::csr_op_e      csr_op_i,
  input  logic                   csr_op_en_i,
  output logic [31:0]            csr_rdata_o,
  input  logic [31:0]            pc_if_i,
  input  logic [31:0]            pc_id_i,
  input  logic [31:0]            lsu_addr_i,
  input  logic                   lsu_req_i,
  input  logic                   lsu_is_store_i,
  output logic                   pmp_err_o,
  output logic                   data_access_fault_o,
  output logic                   instr_access_fault_o,
  input  logic [DataWidth-1:0]   pmp_cfg_i,
  input  logic [DataWidth-1:0]   pmp_addr_i,
  output logic [DataWidth-1:0]   pmp_cfg_o,
  output logic [DataWidth-1:0]   pmp_addr_o,
  input  logic                   mseccfg_rlb_i,
  input  logic                   mseccfg_mmwp_i,
  input  logic                   mseccfg_mml_i,
  input  ibex_pkg::priv_lvl_e    priv_mode_i
);

  import ibex_pkg::*;

  localparam int unsigned PMPAddrW = 32;
  localparam int unsigned PMPCfgW  = 8;

  logic [3:0][PMPCfgW-1:0] pmp_cfg_rdata;
  logic [PMPNumRegions-1:0][PMPAddrW-1:0] pmp_addr_rdata;

  assign csr_rdata_o = '0;
  assign pmp_err_o = 1'b0;
  assign data_access_fault_o = 1'b0;
  assign instr_access_fault_o = 1'b0;
  assign pmp_cfg_o = '0;
  assign pmp_addr_o = '0;

endmodule

// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

`include "prim_assert.sv"

module ibex_cs_registers #(
  parameter bit               DbgTriggerEn     = 1'b0,
  parameter bit               ICache           = 1'b0,
  parameter int unsigned      MHPMCounterNum   = 8,
  parameter int unsigned      MHPMCounterWidth = 40,
  parameter bit               PMPEnable        = 1'b0,
  parameter int unsigned      PMPGranularity   = 0,
  parameter int unsigned      PMPNumRegions    = 4,
  parameter bit               RV32E            = 1'b0
) (
  input  logic                     clk_i,
  input  logic                     rst_ni,
  input  logic                     csr_access_i,
  input  ibex_pkg::csr_num_e       csr_addr_i,
  input  logic [31:0]              csr_wdata_i,
  input  ibex_pkg::csr_op_e        csr_op_i,
  input  logic                     csr_op_en_i,
  output logic [31:0]              csr_rdata_o,
  output logic                     illegal_csr_insn_o,
  output logic [63:0]              mcycle_o,
  output logic [63:0]              minstret_o,
  output logic [63:0]              mhpmcounter_o [32],
  output logic [MHPMCounterNum-1:0] mhpmevent_o [32]
);

  import ibex_pkg::*;

  localparam int unsigned CounterWidth = MHPMCounterWidth < 32 ? 32 : MHPMCounterWidth;

  logic [31:0] mcycle_lo, mcycle_hi;
  logic [31:0] minstret_lo, minstret_hi;
  logic [31:0] mhpmcounter_lo [32];
  logic [31:0] mhpmcounter_hi [32];
  logic [31:0] mhpmevent [32];
  logic [31:0] mcountinhibit_q, mcountinhibit_d;

  logic [3:0][7:0] pmpcfg_q [4];
  logic [3:0][7:0] pmpcfg_d [4];
  logic [31:0] pmpaddr_q [16];
  logic [31:0] pmpaddr_d [16];
  logic [31:0] mseccfg_q, mseccfg_d;
  logic [31:0] mseccfgh_q, mseccfgh_d;

  logic [31:0] csr_wdata_int;
  logic csr_we;
  logic [31:0] csr_rdata_int;
  logic illegal_csr;

  assign csr_wdata_int = csr_wdata_i;

  always_comb begin
    csr_we = 1'b0;
    case (csr_op_i)
      CSR_OP_READ:  csr_we = 1'b0;
      CSR_OP_WRITE: csr_we = csr_op_en_i;
      CSR_OP_SET:   csr_we = csr_op_en_i && (csr_wdata_int != '0);
      CSR_OP_CLEAR: csr_we = csr_op_en_i && (csr_wdata_int != '0);
      default:      csr_we = 1'b0;
    endcase
  end

  logic [31:0] csr_read_data;

  always_comb begin
    csr_read_data = '0;
    illegal_csr = 1'b0;

    if (csr_access_i && csr_op_en_i) begin
      case (csr_addr_i)
        CSR_MCOUNTINHIBIT: begin
          csr_read_data = mcountinhibit_q;
        end

        CSR_MCYCLE:    csr_read_data = mcycle_lo;
        CSR_MCYCLEH:   csr_read_data = mcycle_hi;
        CSR_MINSTRET:  csr_read_data = minstret_lo;
        CSR_MINSTRETH: csr_read_data = minstret_hi;

        CSR_MSECCFG: begin
          if (PMPEnable) begin
            csr_read_data = mseccfg_q;
          end else begin
            illegal_csr = 1'b1;
          end
        end
        CSR_MSECCFGH: begin
          if (PMPEnable) begin
            csr_read_data = mseccfgh_q;
          end else begin
            illegal_csr = 1'b1;
          end
        end

        CSR_PMPCFG0: begin
          if (PMPEnable) begin
            csr_read_data = {pmpcfg_q[0][3], pmpcfg_q[0][2], pmpcfg_q[0][1], pmpcfg_q[0][0]};
          end else begin
            illegal_csr = 1'b1;
          end
        end
        CSR_PMPCFG1: begin
          if (PMPEnable && PMPNumRegions > 4) begin
            csr_read_data = {pmpcfg_q[1][3], pmpcfg_q[1][2], pmpcfg_q[1][1], pmpcfg_q[1][0]};
          end else begin
            illegal_csr = 1'b1;
          end
        end
        CSR_PMPCFG2: begin
          if (PMPEnable && PMPNumRegions > 8) begin
            csr_read_data = {pmpcfg_q[2][3], pmpcfg_q[2][2], pmpcfg_q[2][1], pmpcfg_q[2][0]};
          end else begin
            illegal_csr = 1'b1;
          end
        end
        CSR_PMPCFG3: begin
          if (PMPEnable && PMPNumRegions > 12) begin
            csr_read_data = {pmpcfg_q[3][3], pmpcfg_q[3][2], pmpcfg_q[3][1], pmpcfg_q[3][0]};
          end else begin
            illegal_csr = 1'b1;
          end
        end

        CSR_PMPADDR0:  begin if (PMPEnable && PMPNumRegions > 0)  csr_read_data = pmpaddr_q[0];  else illegal_csr = 1'b1; end
        CSR_PMPADDR1:  begin if (PMPEnable && PMPNumRegions > 1)  csr_read_data = pmpaddr_q[1];  else illegal_csr = 1'b1; end
        CSR_PMPADDR2:  begin if (PMPEnable && PMPNumRegions > 2)  csr_read_data = pmpaddr_q[2];  else illegal_csr = 1'b1; end
        CSR_PMPADDR3:  begin if (PMPEnable && PMPNumRegions > 3)  csr_read_data = pmpaddr_q[3];  else illegal_csr = 1'b1; end
        CSR_PMPADDR4:  begin if (PMPEnable && PMPNumRegions > 4)  csr_read_data = pmpaddr_q[4];  else illegal_csr = 1'b1; end
        CSR_PMPADDR5:  begin if (PMPEnable && PMPNumRegions > 5)  csr_read_data = pmpaddr_q[5];  else illegal_csr = 1'b1; end
        CSR_PMPADDR6:  begin if (PMPEnable && PMPNumRegions > 6)  csr_read_data = pmpaddr_q[6];  else illegal_csr = 1'b1; end
        CSR_PMPADDR7:  begin if (PMPEnable && PMPNumRegions > 7)  csr_read_data = pmpaddr_q[7];  else illegal_csr = 1'b1; end
        CSR_PMPADDR8:  begin if (PMPEnable && PMPNumRegions > 8)  csr_read_data = pmpaddr_q[8];  else illegal_csr = 1'b1; end
        CSR_PMPADDR9:  begin if (PMPEnable && PMPNumRegions > 9)  csr_read_data = pmpaddr_q[9];  else illegal_csr = 1'b1; end
        CSR_PMPADDR10: begin if (PMPEnable && PMPNumRegions > 10) csr_read_data = pmpaddr_q[10]; else illegal_csr = 1'b1; end
        CSR_PMPADDR11: begin if (PMPEnable && PMPNumRegions > 11) csr_read_data = pmpaddr_q[11]; else illegal_csr = 1'b1; end
        CSR_PMPADDR12: begin if (PMPEnable && PMPNumRegions > 12) csr_read_data = pmpaddr_q[12]; else illegal_csr = 1'b1; end
        CSR_PMPADDR13: begin if (PMPEnable && PMPNumRegions > 13) csr_read_data = pmpaddr_q[13]; else illegal_csr = 1'b1; end
        CSR_PMPADDR14: begin if (PMPEnable && PMPNumRegions > 14) csr_read_data = pmpaddr_q[14]; else illegal_csr = 1'b1; end
        CSR_PMPADDR15: begin if (PMPEnable && PMPNumRegions > 15) csr_read_data = pmpaddr_q[15]; else illegal_csr = 1'b1; end

        CSR_MHPMEVENT3:  begin if (MHPMCounterNum > 0)  csr_read_data = mhpmevent[0];  else illegal_csr = 1'b1; end
        CSR_MHPMEVENT4:  begin if (MHPMCounterNum > 1)  csr_read_data = mhpmevent[1];  else illegal_csr = 1'b1; end
        CSR_MHPMEVENT5:  begin if (MHPMCounterNum > 2)  csr_read_data = mhpmevent[2];  else illegal_csr = 1'b1; end
        CSR_MHPMEVENT6:  begin if (MHPMCounterNum > 3)  csr_read_data = mhpmevent[3];  else illegal_csr = 1'b1; end
        CSR_MHPMEVENT7:  begin if (MHPMCounterNum > 4)  csr_read_data = mhpmevent[4];  else illegal_csr = 1'b1; end
        CSR_MHPMEVENT8:  begin if (MHPMCounterNum > 5)  csr_read_data = mhpmevent[5];  else illegal_csr = 1'b1; end
        CSR_MHPMEVENT9:  begin if (MHPMCounterNum > 6)  csr_read_data = mhpmevent[6];  else illegal_csr = 1'b1; end
        CSR_MHPMEVENT10: begin if (MHPMCounterNum > 7)  csr_read_data = mhpmevent[7];  else illegal_csr = 1'b1; end
        CSR_MHPMEVENT11: begin if (MHPMCounterNum > 8)  csr_read_data = mhpmevent[8];  else illegal_csr = 1'b1; end
        CSR_MHPMEVENT12: begin if (MHPMCounterNum > 9)  csr_read_data = mhpmevent[9];  else illegal_csr = 1'b1; end
        CSR_MHPMEVENT13: begin if (MHPMCounterNum > 10) csr_read_data = mhpmevent[10]; else illegal_csr = 1'b1; end
