        CSR_MHPMCOUNTER16: begin if (MHPMCounterNum > 13) csr_read_data = mhpmcounter_lo[13]; else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER17: begin if (MHPMCounterNum > 14) csr_read_data = mhpmcounter_lo[14]; else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER18: begin if (MHPMCounterNum > 15) csr_read_data = mhpmcounter_lo[15]; else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER19: begin if (MHPMCounterNum > 16) csr_read_data = mhpmcounter_lo[16]; else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER20: begin if (MHPMCounterNum > 17) csr_read_data = mhpmcounter_lo[17]; else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER21: begin if (MHPMCounterNum > 18) csr_read_data = mhpmcounter_lo[18]; else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER22: begin if (MHPMCounterNum > 19) csr_read_data = mhpmcounter_lo[19]; else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER23: begin if (MHPMCounterNum > 20) csr_read_data = mhpmcounter_lo[20]; else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER24: begin if (MHPMCounterNum > 21) csr_read_data = mhpmcounter_lo[21]; else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER25: begin if (MHPMCounterNum > 22) csr_read_data = mhpmcounter_lo[22]; else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER26: begin if (MHPMCounterNum > 23) csr_read_data = mhpmcounter_lo[23]; else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER27: begin if (MHPMCounterNum > 24) csr_read_data = mhpmcounter_lo[24]; else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER28: begin if (MHPMCounterNum > 25) csr_read_data = mhpmcounter_lo[25]; else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER29: begin if (MHPMCounterNum > 26) csr_read_data = mhpmcounter_lo[26]; else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER30: begin if (MHPMCounterNum > 27) csr_read_data = mhpmcounter_lo[27]; else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER31: begin if (MHPMCounterNum > 28) csr_read_data = mhpmcounter_lo[28]; else illegal_csr = 1'b1; end

        CSR_MHPMCOUNTER3H:  begin if (MHPMCounterNum > 0)  csr_read_data = mhpmcounter_hi[0];  else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER4H:  begin if (MHPMCounterNum > 1)  csr_read_data = mhpmcounter_hi[1];  else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER5H:  begin if (MHPMCounterNum > 2)  csr_read_data = mhpmcounter_hi[2];  else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER6H:  begin if (MHPMCounterNum > 3)  csr_read_data = mhpmcounter_hi[3];  else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER7H:  begin if (MHPMCounterNum > 4)  csr_read_data = mhpmcounter_hi[4];  else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER8H:  begin if (MHPMCounterNum > 5)  csr_read_data = mhpmcounter_hi[5];  else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER9H:  begin if (MHPMCounterNum > 6)  csr_read_data = mhpmcounter_hi[6];  else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER10H: begin if (MHPMCounterNum > 7)  csr_read_data = mhpmcounter_hi[7];  else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER11H: begin if (MHPMCounterNum > 8)  csr_read_data = mhpmcounter_hi[8];  else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER12H: begin if (MHPMCounterNum > 9)  csr_read_data = mhpmcounter_hi[9];  else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER13H: begin if (MHPMCounterNum > 10) csr_read_data = mhpmcounter_hi[10]; else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER14H: begin if (MHPMCounterNum > 11) csr_read_data = mhpmcounter_hi[11]; else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER15H: begin if (MHPMCounterNum > 12) csr_read_data = mhpmcounter_hi[12]; else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER16H: begin if (MHPMCounterNum > 13) csr_read_data = mhpmcounter_hi[13]; else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER17H: begin if (MHPMCounterNum > 14) csr_read_data = mhpmcounter_hi[14]; else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER18H: begin if (MHPMCounterNum > 15) csr_read_data = mhpmcounter_hi[15]; else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER19H: begin if (MHPMCounterNum > 16) csr_read_data = mhpmcounter_hi[16]; else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER20H: begin if (MHPMCounterNum > 17) csr_read_data = mhpmcounter_hi[17]; else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER21H: begin if (MHPMCounterNum > 18) csr_read_data = mhpmcounter_hi[18]; else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER22H: begin if (MHPMCounterNum > 19) csr_read_data = mhpmcounter_hi[19]; else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER23H: begin if (MHPMCounterNum > 20) csr_read_data = mhpmcounter_hi[20]; else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER24H: begin if (MHPMCounterNum > 21) csr_read_data = mhpmcounter_hi[21]; else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER25H: begin if (MHPMCounterNum > 22) csr_read_data = mhpmcounter_hi[22]; else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER26H: begin if (MHPMCounterNum > 23) csr_read_data = mhpmcounter_hi[23]; else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER27H: begin if (MHPMCounterNum > 24) csr_read_data = mhpmcounter_hi[24]; else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER28H: begin if (MHPMCounterNum > 25) csr_read_data = mhpmcounter_hi[25]; else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER29H: begin if (MHPMCounterNum > 26) csr_read_data = mhpmcounter_hi[26]; else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER30H: begin if (MHPMCounterNum > 27) csr_read_data = mhpmcounter_hi[27]; else illegal_csr = 1'b1; end
        CSR_MHPMCOUNTER31H: begin if (MHPMCounterNum > 28) csr_read_data = mhpmcounter_hi[28]; else illegal_csr = 1'b1; end

        default: illegal_csr = 1'b1;
      endcase
    end else begin
      illegal_csr = csr_access_i;
    end
  end

  assign csr_rdata_o = csr_read_data;
  assign illegal_csr_insn_o = illegal_csr;

  logic [31:0] csr_write_val;
  always_comb begin
    case (csr_op_i)
      CSR_OP_READ:  csr_write_val = '0;
      CSR_OP_WRITE: csr_write_val = csr_wdata_int;
      CSR_OP_SET:   csr_write_val = csr_read_data | csr_wdata_int;
      CSR_OP_CLEAR: csr_write_val = csr_read_data & ~csr_wdata_int;
      default:      csr_write_val = '0;
    endcase
  end

  assign mcountinhibit_d = csr_we && (csr_addr_i == CSR_MCOUNTINHIBIT) ? csr_write_val : mcountinhibit_q;

  logic [31:0] mcountinhibit_val;
  assign mcountinhibit_val = mcountinhibit_q;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      mcountinhibit_q <= '0;
    end else begin
      mcountinhibit_q <= mcountinhibit_d;
    end
  end

  genvar pmpcfg_gi, pmpaddr_gi;

  for (pmpcfg_gi = 0; pmpcfg_gi < 4; pmpcfg_gi++) begin : gen_pmpcfg
    logic [31:0] pmpcfg_wr_data;
    logic [3:0][7:0] pmpcfg_lock;
    logic pmpcfg_region_locked [4];
    logic pmpcfg_we;

    assign pmpcfg_we = PMPEnable && csr_we && (csr_addr_i == (CSR_PMPCFG0 + pmpcfg_gi[11:0]));

    for (int r = 0; r < 4; r++) begin : gen_lock
      assign pmpcfg_region_locked[r] = pmpcfg_q[pmpcfg_gi][r][7];

      always_comb begin
        pmpcfg_lock[r] = '0;
        if (mseccfg_q[0] == 1'b0) begin
          if (pmpcfg_region_locked[r]) begin
            pmpcfg_lock[r] = 8'hFF;
          end
        end
      end
    end

    always_comb begin
      pmpcfg_d[pmpcfg_gi] = pmpcfg_q[pmpcfg_gi];
      if (pmpcfg_we) begin
        for (int r = 0; r < 4; r++) begin
          if (pmpcfg_gi * 4 + r < PMPNumRegions) begin
            logic [7:0] new_cfg;
            new_cfg = csr_write_val[r*8+:8];
            new_cfg[6:5] = 2'b00;
            if (mseccfg_q[0] == 1'b0) begin
              if (new_cfg[1:0] == 2'b10) begin
                new_cfg[1:0] = 2'b00;
              end
            end
            pmpcfg_d[pmpcfg_gi][r] = (pmpcfg_q[pmpcfg_gi][r] & pmpcfg_lock[r]) | (new_cfg & ~pmpcfg_lock[r]);
          end else begin
            pmpcfg_d[pmpcfg_gi][r] = 8'h00;
          end
        end
      end
    end

    always_ff @(posedge clk_i or negedge rst_ni) begin
      if (!rst_ni) begin
        pmpcfg_q[pmpcfg_gi] <= '{default: '0};
      end else begin
        pmpcfg_q[pmpcfg_gi] <= pmpcfg_d[pmpcfg_gi];
      end
    end
  end

  for (pmpaddr_gi = 0; pmpaddr_gi < 16; pmpaddr_gi++) begin : gen_pmpaddr
    logic pmpaddr_locked;
    logic pmpaddr_we;
    logic [7:0] pmpcfg_entry;
    integer pmpcfg_idx, pmpcfg_region;

    assign pmpcfg_idx = pmpaddr_gi / 4;
    assign pmpcfg_region = pmpaddr_gi % 4;
    assign pmpcfg_entry = pmpcfg_q[pmpcfg_idx][pmpcfg_region];

    assign pmpaddr_locked = pmpcfg_entry[7];

    assign pmpaddr_we = PMPEnable && csr_we && (csr_addr_i == (CSR_PMPADDR0 + pmpaddr_gi[11:0]));

    always_comb begin
      pmpaddr_d[pmpaddr_gi] = pmpaddr_q[pmpaddr_gi];
      if (pmpaddr_we && !pmpaddr_locked) begin
        pmpaddr_d[pmpaddr_gi] = csr_write_val;
      end
    end

    always_ff @(posedge clk_i or negedge rst_ni) begin
      if (!rst_ni) begin
        pmpaddr_q[pmpaddr_gi] <= '0;
      end else begin
        pmpaddr_q[pmpaddr_gi] <= pmpaddr_d[pmpaddr_gi];
      end
    end
  end

  always_comb begin
    mseccfg_d = mseccfg_q;
    if (PMPEnable && csr_we && (csr_addr_i == CSR_MSECCFG)) begin
      logic [2:0] new_bits;
      new_bits = csr_write_val[2:0];
      if ((mseccfg_q & 'h4) == 0) begin
        logic any_locked;
        any_locked = 1'b0;
        for (pmpcfg_gi = 0; pmpcfg_gi < 4; pmpcfg_gi++) begin
          for (int r = 0; r < 4; r++) begin
            if (pmpcfg_q[pmpcfg_gi][r][7]) any_locked = 1'b1;
          end
        end
        if (any_locked) new_bits[2] = 1'b0;
      end
      mseccfg_d[2:0] = (mseccfg_q[2:0] & 'h4) | (new_bits[2] ? 'h4 : 3'b0) | (new_bits[1] ? 'h2 : (mseccfg_q[1] ? 'h2 : 0)) | (new_bits[0] ? 'h1 : (mseccfg_q[0] ? 'h1 : 0));
      mseccfg_d = (mseccfg_q & ~32'h7) | (new_bits & 32'h7);
      if ((mseccfg_q & 'h2) != 0) mseccfg_d[1] = 1'b1;
      if ((mseccfg_q & 'h1) != 0) mseccfg_d[0] = 1'b1;
      if ((mseccfg_q & 'h4) == 0) begin
        logic any_locked2;
        any_locked2 = 1'b0;
        for (pmpcfg_gi = 0; pmpcfg_gi < 4; pmpcfg_gi++) begin
          for (int r = 0; r < 4; r++) begin
            if (pmpcfg_q[pmpcfg_gi][r][7]) any_locked2 = 1'b1;
          end
        end
        if (any_locked2) mseccfg_d[2] = mseccfg_q[2];
      end
    end
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      mseccfg_q <= '0;
    end else begin
      mseccfg_q <= mseccfg_d;
    end
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      mseccfgh_q <= '0;
    end else if (PMPEnable && csr_we && (csr_addr_i == CSR_MSECCFGH)) begin
    end
  end
  assign mseccfgh_d = '0;

  for (genvar ev = 0; ev < 32; ev++) begin : gen_mhpmevent
    always_ff @(posedge clk_i or negedge rst_ni) begin
      if (!rst_ni) begin
        mhpmevent[ev] <= (ev < MHPMCounterNum) ? (32'b1 << ev) : '0;
      end else if (csr_we) begin
        if (ev == 0  && csr_addr_i == CSR_MHPMEVENT3  && MHPMCounterNum > 0)  mhpmevent[ev] <= csr_write_val;
        else if (ev == 1  && csr_addr_i == CSR_MHPMEVENT4  && MHPMCounterNum > 1)  mhpmevent[ev] <= csr_write_val;
        else if (ev == 2  && csr_addr_i == CSR_MHPMEVENT5  && MHPMCounterNum > 2)  mhpmevent[ev] <= csr_write_val;
        else if (ev == 3  && csr_addr_i == CSR_MHPMEVENT6  && MHPMCounterNum > 3)  mhpmevent[ev] <= csr_write_val;
        else if (ev == 4  && csr_addr_i == CSR_MHPMEVENT7  && MHPMCounterNum > 4)  mhpmevent[ev] <= csr_write_val;
        else if (ev == 5  && csr_addr_i == CSR_MHPMEVENT8  && MHPMCounterNum > 5)  mhpmevent[ev] <= csr_write_val;
        else if (ev == 6  && csr_addr_i == CSR_MHPMEVENT9  && MHPMCounterNum > 6)  mhpmevent[ev] <= csr_write_val;
        else if (ev == 7  && csr_addr_i == CSR_MHPMEVENT10 && MHPMCounterNum > 7)  mhpmevent[ev] <= csr_write_val;
        else if (ev == 8  && csr_addr_i == CSR_MHPMEVENT11 && MHPMCounterNum > 8)  mhpmevent[ev] <= csr_write_val;
        else if (ev == 9  && csr_addr_i == CSR_MHPMEVENT12 && MHPMCounterNum > 9)  mhpmevent[ev] <= csr_write_val;
        else if (ev == 10 && csr_addr_i == CSR_MHPMEVENT13 && MHPMCounterNum > 10) mhpmevent[ev] <= csr_write_val;
        else if (ev == 11 && csr_addr_i == CSR_MHPMEVENT14 && MHPMCounterNum > 11) mhpmevent[ev] <= csr_write_val;
        else if (ev == 12 && csr_addr_i == CSR_MHPMEVENT15 && MHPMCounterNum > 12) mhpmevent[ev] <= csr_write_val;
        else if (ev == 13 && csr_addr_i == CSR_MHPMEVENT16 && MHPMCounterNum > 13) mhpmevent[ev] <= csr_write_val;
        else if (ev == 14 && csr_addr_i == CSR_MHPMEVENT17 && MHPMCounterNum > 14) mhpmevent[ev] <= csr_write_val;
        else if (ev == 15 && csr_addr_i == CSR_MHPMEVENT18 && MHPMCounterNum > 15) mhpmevent[ev] <= csr_write_val;
        else if (ev == 16 && csr_addr_i == CSR_MHPMEVENT19 && MHPMCounterNum > 16) mhpmevent[ev] <= csr_write_val;
        else if (ev == 17 && csr_addr_i == CSR_MHPMEVENT20 && MHPMCounterNum > 17) mhpmevent[ev] <= csr_write_val;
        else if (ev == 18 && csr_addr_i == CSR_MHPMEVENT21 && MHPMCounterNum > 18) mhpmevent[ev] <= csr_write_val;
        else if (ev == 19 && csr_addr_i == CSR_MHPMEVENT22 && MHPMCounterNum > 19) mhpmevent[ev] <= csr_write_val;
        else if (ev == 20 && csr_addr_i == CSR_MHPMEVENT23 && MHPMCounterNum > 20) mhpmevent[ev] <= csr_write_val;
        else if (ev == 21 && csr_addr_i == CSR_MHPMEVENT24 && MHPMCounterNum > 21) mhpmevent[ev] <= csr_write_val;
        else if (ev == 22 && csr_addr_i == CSR_MHPMEVENT25 && MHPMCounterNum > 22) mhpmevent[ev] <= csr_write_val;
        else if (ev == 23 && csr_addr_i == CSR_MHPMEVENT26 && MHPMCounterNum > 23) mhpmevent[ev] <= csr_write_val;
        else if (ev == 24 && csr_addr_i == CSR_MHPMEVENT27 && MHPMCounterNum > 24) mhpmevent[ev] <= csr_write_val;
        else if (ev == 25 && csr_addr_i == CSR_MHPMEVENT28 && MHPMCounterNum > 25) mhpmevent[ev] <= csr_write_val;
        else if (ev == 26 && csr_addr_i == CSR_MHPMEVENT29 && MHPMCounterNum > 26) mhpmevent[ev] <= csr_write_val;
        else if (ev == 27 && csr_addr_i == CSR_MHPMEVENT30 && MHPMCounterNum > 27) mhpmevent[ev] <= csr_write_val;
        else if (ev == 28 && csr_addr_i == CSR_MHPMEVENT31 && MHPMCounterNum > 28) mhpmevent[ev] <= csr_write_val;
      end
    end
  end

  logic mcycle_inc, minstret_inc;
  assign mcycle_inc = 1'b1;
  assign minstret_inc = 1'b0;

  ibex_counter #(
    .CounterWidth (CounterWidth),
    .Stub         (1'b0)
  ) mcycle_counter (
    .clk_i         (clk_i),
    .rst_ni        (rst_ni),
    .counter_inc_i (mcycle_inc && !mcountinhibit_val[0]),
    .counterh_we_i (csr_we && (csr_addr_i == CSR_MCYCLEH)),
    .counter_we_i  (csr_we && (csr_addr_i == CSR_MCYCLE)),
    .counter_val_i (csr_write_val),
    .counter_val_o ({mcycle_hi, mcycle_lo})
  );

  ibex_counter #(
    .CounterWidth (CounterWidth),
    .Stub         (1'b0)
  ) minstret_counter (
    .clk_i         (clk_i),
    .rst_ni        (rst_ni),
    .counter_inc_i (minstret_inc && !mcountinhibit_val[2]),
    .counterh_we_i (csr_we && (csr_addr_i == CSR_MINSTRETH)),
    .counter_we_i  (csr_we && (csr_addr_i == CSR_MINSTRET)),
    .counter_val_i (csr_write_val),
    .counter_val_o ({minstret_hi, minstret_lo})
  );

  for (genvar ci = 0; ci < 32; ci++) begin : gen_mhpmcounter
    localparam int unsigned CounterIdx = ci + 3;
    localparam int unsigned EventIdx = ci;

    logic counter_inc;
    logic counter_we, counterh_we;

    assign counter_inc = !mcountinhibit_val[CounterIdx] && (EventIdx < MHPMCounterNum);

    assign counter_we  = csr_we && (csr_addr_i == (CSR_MHPMCOUNTER3 + ci[11:0]));
    assign counterh_we = csr_we && (csr_addr_i == (CSR_MHPMCOUNTER3H + ci[11:0]));

    if (ci < MHPMCounterNum) begin : gen_implemented
      ibex_counter #(
        .CounterWidth (CounterWidth),
        .Stub         (1'b0)
      ) u_counter (
        .clk_i         (clk_i),
        .rst_ni        (rst_ni),
        .counter_inc_i (counter_inc),
        .counterh_we_i (counterh_we),
        .counter_we_i  (counter_we),
        .counter_val_i (csr_write_val),
        .counter_val_o ({mhpmcounter_hi[ci], mhpmcounter_lo[ci]})
      );
    end else begin : gen_stub
      assign mhpmcounter_lo[ci] = '0;
      assign mhpmcounter_hi[ci] = '0;
    end
  end

  assign mcycle_o = {mcycle_hi, mcycle_lo};
  assign minstret_o = {minstret_hi, minstret_lo};

  for (genvar co = 0; co < 32; co++) begin : gen_mhpmcounter_o
    assign mhpmcounter_o[co] = {mhpmcounter_hi[co], mhpmcounter_lo[co]};
    assign mhpmevent_o[co] = (MHPMCounterNum > 0 && co < MHPMCounterNum) ? mhpmevent[co] : '0;
  end

  `ASSERT_INIT(PMPNumRegionsLegal, PMPNumRegions <= PMP_MAX_REGIONS)

endmodule

